//
// Compiles a whole set of sources -- a cook, `compile -All` -- so that whether it succeeds does not
// depend on the order the files were listed in.
//
// A material that calls a function generated by another source loads that function as an asset. On a
// clean workspace the asset exists only once the other source has been compiled, so a list that puts the
// caller first failed the caller even though the callee was built moments later. Extension order (.dsf
// first) covers the common case and nothing else: a function calling a function, or a .dss whose exported
// function another source uses, are all the same shape. So the set is compiled in passes. A failure is
// held back, not reported, while the pass it happened in still built something; the next pass retries it
// against what is now on disk. Once a pass builds nothing new, every remaining failure is final -- a real
// error, or a dependency that never appears (a missing source, a cycle) -- and is reported with the
// message of its last attempt.

#pragma once

#include "CoreMinimal.h"

#include "DreamShaderCompilerInterface.h"
#include "Templates/Function.h"

namespace UE::DreamShader::Editor::Private
{
	/** The final outcome of one source in a batch. */
	struct FDreamShaderBatchCompileEntry
	{
		FString SourceFile;

		/** The last attempt's result. */
		FDreamShaderCompileResult Result;

		/** How many times the source was compiled; more than 1 means it waited for a dependency. */
		int32 Attempts = 0;
	};

	/**
	 * Material-function sources (.dsf) first, then everything else; within each group by path, ignoring
	 * case. Not a dependency order -- CompileDreamShaderSourcesInBatch does not need one -- but it makes
	 * the common case build in one pass and the log read the same on every machine.
	 */
	void SortDreamShaderSourcesForBatch(TArray<FString>& InOutSourceFiles);

	/**
	 * Compiles every file in `SourceFiles`, in the order given, retrying failures as described above.
	 * Each request is `RequestTemplate` with its SourceFilePath set. `OnFinal` is called once per file
	 * when its outcome is final: at once for a success, after the last pass for a failure. Returns the
	 * number of files that failed.
	 */
	int32 CompileDreamShaderSourcesInBatch(
		IDreamShaderCompiler& Compiler,
		const TArray<FString>& SourceFiles,
		const FDreamShaderCompileRequest& RequestTemplate,
		TFunctionRef<void(const FDreamShaderBatchCompileEntry&)> OnFinal);
}
